// 物料清单窗口图片单元格：按物料key从 IndexedDB 懒加载图片
const PrBomImgCell = ({ k }: { k: string }) => {
  const [src, setSrc] = useState('');
  useEffect(() => {
    let cancelled = false;
    if (k) imgDB.get(k).then(v => { if (!cancelled && v) setSrc(v); });
    return () => { cancelled = true; };
  }, [k]);
  return src
    ? <img src={src} alt="" style={{ width: 32, height: 32, objectFit: 'cover', borderRadius: 4, border: '1px solid #eee' }} />
    : <div style={{ width: 32, height: 32, background: '#fafafa', border: '1px dashed #d9d9d9', borderRadius: 4 }} />;
};
// 加工订单图片单元格：按商品编码查找产品key，再从 IndexedDB 懒加载图片
const PrPoImgCell = ({ productCode, owner }: { productCode: string; owner: string }) => {
  const [src, setSrc] = useState('');
  useEffect(() => {
    let cancelled = false;
    if (!productCode || !owner) return;
    (async () => {
      try {
        const stored = localStorage.getItem(`pageData_basic-data_product-list_${owner}`);
        if (stored) {
          const products = JSON.parse(stored);
          const product = products.find((p: any) => p.productCode === productCode);
          if (product?.key) {
            const v = await imgDB.get(product.key);
            if (!cancelled && v) setSrc(v);
          }
        }
      } catch { /* ignore */ }
    })();
    return () => { cancelled = true; };
  }, [productCode, owner]);
  return src
    ? <img src={src} alt="" style={{ width: 32, height: 32, objectFit: 'cover', borderRadius: 4, border: '1px solid #eee' }} />
    : <div style={{ width: 32, height: 32, background: '#fafafa', border: '1px dashed #d9d9d9', borderRadius: 4 }} />;
};

// 产品图片共享读取：与新品研发同一图片库（IndexedDB prodImages，key=产品key），优先共享库、回退记录image字段
const useSharedProductImg = (recKey: string, fallback?: string) => {
  const [src, setSrc] = useState(fallback || '');
  useEffect(() => {
    let cancelled = false;
    if (!recKey) return;
    imgDB.get(recKey).then(v => { if (!cancelled && v) setSrc(v); });
    return () => { cancelled = true; };
  }, [recKey]);
  return src;
};

// 商品列表图片单元格：默认显示共享库（新品研发）图片，悬停浮层支持预览/删除，点击换图
const ProductImageCell = ({ record, val, onUpload, onPreview, onRemove }: {
  record: any; val: string;
  onUpload: (r: any) => void;
  onPreview: (p: { url: string; visible: boolean }) => void;
  onRemove: (r: any) => void;
}) => {
  const src = useSharedProductImg(record?.key || '', val);
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
      {src ? (
        <div style={{ position: 'relative', display: 'inline-block', width: 44, height: 44 }}
          onMouseEnter={(e) => { const overlay = e.currentTarget.querySelector('.img-overlay') as HTMLElement; if (overlay) overlay.style.opacity = '1'; }}
          onMouseLeave={(e) => { const overlay = e.currentTarget.querySelector('.img-overlay') as HTMLElement; if (overlay) overlay.style.opacity = '0'; }}
        >
          <img src={src} alt="" style={{ width: 40, height: 40, objectFit: 'cover', borderRadius: 4, cursor: 'pointer', display: 'block' }}
            onClick={() => onUpload(record)} />
          <div className="img-overlay" style={{
            position: 'absolute', top: 0, left: 0, width: 40, height: 40, borderRadius: 4,
            background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'center', justifyContent: 'center',
            gap: 6, opacity: 0, transition: 'opacity 0.2s', cursor: 'default',
          }}>
            <Tooltip title="预览图片">
              <EyeOutlined
                onClick={(e) => { e.stopPropagation(); onPreview({ url: src, visible: true }); }}
                style={{ fontSize: 14, color: '#fff', cursor: 'pointer', padding: 2 }} />
            </Tooltip>
            <Tooltip title="删除图片">
              <CloseOutlined
                onClick={(e) => { e.stopPropagation(); onRemove(record); }}
                style={{ fontSize: 14, color: '#ff4d4f', cursor: 'pointer', padding: 2 }} />
            </Tooltip>
          </div>
        </div>
      ) : (
        <Tooltip title="点击上传图片（新品研发图片自动同步显示）">
          <div
            onClick={() => onUpload(record)}
            style={{
              width: 40, height: 40, border: '1px dashed #d9d9d9', borderRadius: 4,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              cursor: 'pointer', color: '#bfbfbf', transition: 'all 0.2s',
            }}
          >
            <CameraOutlined style={{ fontSize: 16 }} />
          </div>
        </Tooltip>
      )}
    </div>
  );
};

