// 孤儿数据迁移：历史上部分处理器取 owner 失败，把记录误写到 _default / 空 owner 的存储键下，
// 页面读取时合并到当前账号列表（按 key / id / 同订单同状态单据去重），并清理错误键
const mergeStrandedOwnerData = (baseKey: string, current: any[], currentOwner: string): any[] => {
  let merged = current;
  ['default', ''].forEach((badOwner) => {
    // 跳过当前账号自身，避免把当前数据键误当孤儿键删除
    if (badOwner === currentOwner) return;
    const badKey = `${baseKey}_${badOwner}`;
    try {
      const raw = localStorage.getItem(badKey);
      if (!raw) return;
      const stranded = JSON.parse(raw);
      if (!Array.isArray(stranded) || stranded.length === 0) { localStorage.removeItem(badKey); return; }
      const existKeys = new Set(merged.map((r: any) => r.key).filter(Boolean));
      const existIds = new Set(merged.map((r: any) => r.id).filter(Boolean));
      const toAdd = stranded.filter((r: any) => {
        if (r?.key && existKeys.has(r.key)) return false;
        if (r?.id && existIds.has(r.id)) return false;
        // 同订单同状态的单据已存在（如财审对账已补建），不重复添加
        if (r?.orderId && r?.status && merged.some((m: any) => m.orderId === r.orderId && m.status === r.status)) return false;
        return true;
      });
      if (toAdd.length > 0) merged = [...merged, ...toAdd];
      localStorage.removeItem(badKey);
    } catch { /* ignore */ }
  });
  return merged;
};

// 重新审核时是否可跳过财务审核：已通过财审且已付金额与货款总额均未变更；
// 历史数据无财审标记时，存在拣货/生产驳回记录即视为已通过财审（默认跳过）
// 余额支付的订单不需要进入财务审核
const canSkipFinanceAudit = (o: any): boolean => {
  if (!o) return false;
  // 余额支付订单直接跳过财务审核
  if (o.payMethod === '余额支付' || String(o.orderTags || '').includes('余额支付') || String(o.orderTag || '').includes('余额支付')) return true;
  const paid = Number(o.paidAmount) || 0;
  if (o.financeAudited) {
    // 已付金额与上次财审时一致
    const paidUnchanged = paid === (Number(o.financeAuditedAmount) || 0);
    // 当前应付总额与上次财审时一致（货品明细未变更）
    const currentDue = calcOrderDueAmount(o);
    const auditedDue = Number(o.financeAuditedDue) || 0;
    const dueUnchanged = currentDue === auditedDue;
    return paidUnchanged && dueUnchanged;
  }
  const st = String(o.auditStatus || '');
  return st.includes('拣货驳回') || st.includes('生产驳回');
};

// 订单应付总金额 = 货品明细(单价×数量)合计 + 运费
const calcOrderDueAmount = (o: any): number => {
  let items: any[] = [];
  try { items = o?.orderItems ? (typeof o.orderItems === 'string' ? JSON.parse(o.orderItems) : o.orderItems) : []; } catch { items = []; }
  const sum = (Array.isArray(items) ? items : []).reduce((s: number, it: any) => s + (Number(it.price) || 0) * (Number(it.quantity) || 0), 0);
  return sum + (Number(o?.freight) || 0);
};



