// ============ 图片放大预览组件 ============
const ZoomThumb: React.FC<{ src: string; imgKey: string; size?: number }> = ({ src, imgKey, size = 40 }) => {
  const [fullSrc, setFullSrc] = React.useState<string | null>(null);
  const [loaded, setLoaded] = React.useState(false);
  React.useEffect(() => {
    if (!imgKey) return;
    setLoaded(false);
    getFullImage(imgKey).then(url => {
      if (url) { setFullSrc(url); setLoaded(true); }
    });
  }, [imgKey]);
  const displaySrc = loaded && fullSrc ? fullSrc : src;
  return (
    <Popover
      trigger={['hover', 'click']}
      content={<img src={displaySrc} alt="" style={{ maxWidth: 280, maxHeight: 280, objectFit: 'contain' }} />}
      overlayInnerStyle={{ padding: 4 }}
    >
      <img
        src={src}
        alt=""
        style={{ width: size, height: size, objectFit: 'cover', borderRadius: 4, cursor: 'zoom-in', display: 'block' }}
      />
    </Popover>
  );
};

