// ============ 智能地址解析 ============
const parseSmartAddress = (text: string): {
  receiverName?: string; receiverPhone?: string; province?: string; city?: string;
  district?: string; receiverDetail?: string;
} => {
  const result: any = {};
  const lines = text.split(/[\n,，;；\t]/).map(s => s.trim()).filter(Boolean);
  // 提取姓名和电话
  const phoneReg = /1[3-9]\d{9}/;
  const telReg = /\d{3,4}-?\d{7,8}/;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const phoneMatch = line.match(phoneReg);
    const telMatch = line.match(telReg);
    if (phoneMatch) {
      result.receiverPhone = phoneMatch[0];
      const namePart = line.replace(phoneMatch[0], '').trim();
      if (namePart && !result.receiverName) result.receiverName = namePart;
      lines.splice(i, 1); i--;
      continue;
    }
    if (telMatch) {
      result.receiverPhone = telMatch[0];
      const namePart = line.replace(telMatch[0], '').trim();
      if (namePart && !result.receiverName) result.receiverName = namePart;
      lines.splice(i, 1); i--;
      continue;
    }
  }
  // 如果没有从独立行找到姓名，尝试从第一行提取
  if (!result.receiverName && lines.length > 0) {
    const firstName = lines[0].replace(/[\u4e00-\u9fa5]{2,6}(省|市|区|县|镇|乡)/g, '').trim();
    if (firstName && firstName.length <= 6 && !/\d/.test(firstName)) {
      result.receiverName = firstName;
      lines[0] = lines[0].replace(firstName, '').trim();
      if (!lines[0]) lines.shift();
    }
  }
  // 从剩余文本中提取姓名（支持：盛先生收、张总、李四收、王五先生等模式）
  if (!result.receiverName) {
    const namePatterns = [
      /^([\u4e00-\u9fa5]{2,4})(先生|女士|小姐|总|经理|收)$/,
      /^([\u4e00-\u9fa5]{2,4})(先生|女士|小姐|总|经理)$/,
      /^([\u4e00-\u9fa5]{2,4})收$/,
    ];
    for (const pattern of namePatterns) {
      for (let i = 0; i < lines.length; i++) {
        const match = lines[i].match(pattern);
        if (match) {
          result.receiverName = match[1] + (match[2] || '');
          lines[i] = lines[i].replace(match[0], '').trim();
          if (!lines[i]) lines.splice(i, 1);
          break;
        }
      }
      if (result.receiverName) break;
    }
  }
  // 简单省市区匹配（市/区优先按 CHINA_REGIONS 精确匹配，
  // 避免贪婪正则把县级市并入城市，如“温州市瑞安市”）
  const remaining = lines.join(' ');
  const provinceMatch = remaining.match(/([\u4e00-\u9fa5]{2,6}省|[\u4e00-\u9fa5]{2,6}自治区|北京市|天津市|上海市|重庆市)/);
  if (provinceMatch) { result.province = provinceMatch[1]; }
  const afterProvince = (provinceMatch ? remaining.split(provinceMatch[1]).slice(1).join('') : remaining).trim();
  // 市：先按 CHINA_REGIONS 省市列表匹配（长名优先），否则回退非贪婪正则
  let city = '';
  let afterCity = afterProvince;
  const cityKeys = result.province && CHINA_REGIONS[result.province] ? Object.keys(CHINA_REGIONS[result.province]) : [];
  const cityHit = cityKeys.slice().sort((a, b) => b.length - a.length).find(c => afterProvince.startsWith(c));
  if (cityHit) {
    city = cityHit;
    afterCity = afterProvince.slice(cityHit.length).trim();
  } else {
    const cityMatch = afterProvince.match(/^([\u4e00-\u9fa5]{2,6}?市|[\u4e00-\u9fa5]{2,6}自治州|[\u4e00-\u9fa5]{2,6}地区|[\u4e00-\u9fa5]{2,6}盟)/);
    if (cityMatch) { city = cityMatch[1]; afterCity = afterProvince.slice(cityMatch[1].length).trim(); }
  }
  // 直辖市：城市与省同名
  if (!city && result.province && ['北京市', '天津市', '上海市', '重庆市'].includes(result.province)) {
    city = result.province;
    afterCity = afterProvince;
  }
  if (city) result.city = city;
  // 区县：先按 CHINA_REGIONS 该市区县列表匹配（含县级市），否则回退非贪婪正则
  let district = '';
  let afterDistrict = afterCity;
  const districtKeys = result.province && city && CHINA_REGIONS[result.province] && CHINA_REGIONS[result.province][city] ? CHINA_REGIONS[result.province][city] : [];
  const districtHit = districtKeys.slice().sort((a, b) => b.length - a.length).find(d => afterCity.startsWith(d));
  if (districtHit) {
    district = districtHit;
    afterDistrict = afterCity.slice(districtHit.length).trim();
  } else {
    const districtMatch = afterCity.match(/^([\u4e00-\u9fa5]{2,6}[区县旗]|[\u4e00-\u9fa5]{2,6}?市)/);
    if (districtMatch) { district = districtMatch[1]; afterDistrict = afterCity.slice(districtMatch[1].length).trim(); }
  }
  if (district) result.district = district;
  // 剩余部分作为详细地址
  const detail = afterDistrict.replace(/^[\s,，]+/, '').trim();
  if (detail) result.receiverDetail = detail;
  return result;
};

// ============ 付款截图上传组件 ============
// 优先落到云端图片空间（记录里只存 URL，体积小且能跨端同步）；云端不可用时退回本机 base64
const PayScreenshotUpload: React.FC<{
  value?: string; onChange?: (val: string) => void;
  getRef?: () => { module: string; moduleLabel?: string; childKey?: string; childLabel?: string; recordKey: string; recordName?: string; field?: string };
}> = ({ value, onChange, getRef }) => {
  const [previewVisible, setPreviewVisible] = useState(false);
  const [uploading, setUploading] = useState(false);

  const acceptFile = useCallback(async (file: File) => {
    if (!file.type.startsWith('image/')) { message.error('请选择图片文件'); return; }
    if (file.size > 20 * 1024 * 1024) { message.error('图片不能超过 20MB'); return; }
    setUploading(true);
    try {
      const compressed = await compressImageFile(file);
      const ref = getRef ? getRef() : null;
      if (ref && ref.recordKey) {
        try {
          const asset = await uploadImage({
            dataUrl: compressed, thumbDataUrl: compressed, width: 0, height: 0,
            name: ref.recordName || '付款截图', tags: ['付款截图'], ref: { ...ref, field: ref.field || 'payScreenshot' },
          });
          onChange?.(absoluteImageUrl(asset.url));
          return;
        } catch { /* 落云失败→退回本地 */ }
      }
      onChange?.(compressed);
    } catch {
      message.error('图片处理失败');
    } finally {
      setUploading(false);
    }
  }, [onChange, getRef]);

  const handlePaste = useCallback((e: React.ClipboardEvent) => {
    const items = e.clipboardData?.items;
    if (!items) return;
    for (const item of Array.from(items)) {
      if (item.type.startsWith('image/')) {
        const file = item.getAsFile();
        if (!file) continue;
        void acceptFile(file);
        break;
      }
    }
  }, [acceptFile]);
  return (
    <div onPaste={handlePaste} tabIndex={0} style={{ outline: 'none' }}>
      {value ? (
        <div style={{ position: 'relative', display: 'inline-block' }}>
          <img src={value} alt="付款截图" style={{ width: 96, height: 96, objectFit: 'cover', borderRadius: 6, border: '1px solid #d9d9d9', cursor: 'pointer' }}
            onClick={() => setPreviewVisible(true)} />
          <CloseCircleOutlined
            style={{ position: 'absolute', top: -6, right: -6, color: '#ff4d4f', fontSize: 16, cursor: 'pointer', background: '#fff', borderRadius: '50%' }}
            onClick={(e) => { e.stopPropagation(); onChange?.(''); }} />
          <Image src={value} style={{ display: 'none' }} preview={{ visible: previewVisible, onVisibleChange: setPreviewVisible, src: value }} />
        </div>
      ) : (
        <div
          onClick={() => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = () => {
              const file = input.files?.[0]; if (!file) return;
              void acceptFile(file);
            };
            input.click();
          }}
          style={{ width: 96, height: 96, border: '1px dashed #d9d9d9', borderRadius: 6, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', cursor: uploading ? 'progress' : 'pointer', background: '#fafafa' }}
        >
          <PictureOutlined style={{ fontSize: 20, color: '#bbb' }} />
          <span style={{ fontSize: 10, color: '#bbb', marginTop: 4 }}>{uploading ? '上传中…' : '点击或Ctrl+V'}</span>
        </div>
      )}
    </div>
  );
};

