// ============ 优惠输入组件 ============
const DiscountInput: React.FC<{
  value?: string; onChange?: (val: string) => void;
  basePrice?: number; onPriceChange?: (price: number) => void;
}> = ({ value, onChange, basePrice, onPriceChange }) => {
  const parseDiscount = useCallback((input: string): { display: string; price: number } => {
    const trimmed = input.trim();
    if (!trimmed || !basePrice) return { display: '', price: basePrice || 0 };
    // 百分比折扣: 9 = 9折, 90% = 9折, -10% = 减10%
    if (trimmed.endsWith('%')) {
      const num = parseFloat(trimmed);
      if (!isNaN(num)) {
        if (num < 0) {
          // 负百分比 = 折扣 例如 -10% => basePrice * (1 - 10/100)
          const pct = Math.abs(num);
          return { display: `${pct}%折扣`, price: Math.max(0, Number((basePrice * (1 - pct / 100)).toFixed(2))) };
        } else {
          // 正百分比 = 加价 例如 +5% => basePrice * (1 + 5/100)
          return { display: `加价${num}%`, price: Math.max(0, Number((basePrice * (1 + num / 100)).toFixed(2))) };
        }
      }
    }
    const num = parseFloat(trimmed);
    if (!isNaN(num)) {
      if (num > 0 && num < 20) {
        // 小正数 = 折扣 例如 9 = 9折
        return { display: `${num}折`, price: Math.max(0, Number((basePrice * num / 10).toFixed(2))) };
      } else if (num < 0) {
        // 负数 = 减价
        return { display: `减¥${Math.abs(num)}`, price: Math.max(0, Number((basePrice - Math.abs(num)).toFixed(2))) };
      } else {
        // 大正数 = 加价
        return { display: `加¥${num}`, price: Math.max(0, Number((basePrice + num).toFixed(2))) };
      }
    }
    return { display: trimmed, price: basePrice };
  }, [basePrice]);

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
      <Input
        size="small" value={value} placeholder="如:9折/-5/加价3"
        style={{ width: 90, fontSize: 11 }}
        onChange={e => {
          onChange?.(e.target.value);
          const { price } = parseDiscount(e.target.value);
          onPriceChange?.(price);
        }}
        onBlur={e => {
          const { display } = parseDiscount(e.target.value);
          if (display && display !== e.target.value) onChange?.(display);
        }}
      />
    </div>
  );
};

