const loadPickFieldCfg = (owner: string) => {
  const key = `pickListFields_${owner}`;
  const vis: Record<string, boolean> = {};
  PICK_FIELD_DEFAULT_ORDER.forEach(k => { vis[k] = true; });
  let order = [...PICK_FIELD_DEFAULT_ORDER];
  try {
    const raw = JSON.parse(localStorage.getItem(key) || 'null');
    if (raw && Array.isArray(raw.order)) {
      order = raw.order.filter((k: string) => PICK_FIELD_DEFAULT_ORDER.includes(k));
      PICK_FIELD_DEFAULT_ORDER.forEach(k => { if (!order.includes(k)) order.push(k); });
    }
    if (raw && raw.visibility && typeof raw.visibility === 'object') {
      PICK_FIELD_DEFAULT_ORDER.forEach(k => { if (typeof raw.visibility[k] === 'boolean') vis[k] = raw.visibility[k]; });
    }
  } catch { /* ignore */ }
  return { order, visibility: vis };
};

// 自动发起对账设置读取：从未保存过时默认开启（延时1小时、全部客户）
const loadAutoReconSettings = (owner: string) => {
  let s: any = null;
  try { s = JSON.parse(localStorage.getItem('autoReconSettings_' + owner) || 'null'); } catch { /* ignore */ }
  return {
    enabled: s ? !!s.enabled : true,
    delayHours: Number(s?.delayHours) || 1,
    scope: (s?.scope === 'selected' ? 'selected' : 'all') as 'all' | 'selected',
    customers: Array.isArray(s?.customers) ? (s.customers as string[]) : [],
  };
};

/**
 * 本地配额写不进时的上传兜底：直接按内存中的最新 JSON 上传服务端（最多退避重试 3 次）。
 * 背景：同步上传挂在 localStorage 写入成功的钩子上，一旦本地 5MB 配额满，数据只留在本机 IndexedDB，
 * 其他端与换机后都看不到；此处补一条与本地写盘结果无关的直传通道。
 */
const uploadDatasetWithRetry = (key: string, json: string, attempt = 0): void => {
  const delays = [1000, 3000, 8000];
  const retry = () => { if (attempt < delays.length) setTimeout(() => uploadDatasetWithRetry(key, json, attempt + 1), delays[attempt]); };
  flushDatasetUploadAsync(key, json).then(ok => { if (!ok) retry(); }).catch(retry);
};

