  // 合并相同商品编码的商品，汇总数量（相同编码合并为一行，数量累加）
  const mergeItemsByCode = useCallback((items: any[]): any[] => {
    const map = new Map<string, any>();
    items.forEach(it => {
      const code = it.productCode || '';
      if (!code) { map.set(`__empty_${map.size}`, it); return; }
      const existing = map.get(code);
      if (existing) {
        existing.quantity = (Number(existing.quantity) || 0) + (Number(it.quantity) || 0);
        if (it.productionQty !== undefined) existing.productionQty = (Number(existing.productionQty) || 0) + (Number(it.productionQty) || 0);
      } else {
        map.set(code, { ...it });
      }
    });
    return Array.from(map.values());
  }, []);

  // 付款方式：剩余额度查询缓存
  const [orderBalanceCredit, setOrderBalanceCredit] = useState<number | null>(null);
  // 查询客户剩余额度：与客户基础信息"剩余额度"列保持一致 = 有效信用额度(含调整) - (采购总额 - 已收货款)
  const queryCustomerCredit = useCallback((customerName: string): number | null => {
    if (!customerName) return null;
    try {
      const owner = getDataOwner();
      const allCustomers = loadAllCustomersFromStorage();
      // 客户档案命中：名称全等优先，未命中时按主体身份键（账号/公司编号/改名链）归一再找，
      // 避免对方刚改名、档案已刷新而订单仍存旧名时报“未查询到客户剩余额度”
      let c: any = allCustomers.find((r: any) => (r.name || '') === customerName);
      if (!c) { const cid = buildCredIndex(); c = allCustomers.find((r: any) => cid.isSameParty((r.name || ''), customerName)); }
      if (!c) return null;
      const baseCredit = Number(c.credit) || 0;
      // 信用额度调整：与客户列表页 getEffectiveCredit 一致
      let adjustments: any[] = [];
      try { adjustments = JSON.parse(localStorage.getItem(`credit_adjustments_${owner}`) || '[]'); } catch { /* ignore */ }
      const netAdjust = adjustments
        .filter((r: any) => r.customerId === c.id || r.customerName === customerName)
        .reduce((s: number, r: any) => s + (r.type === 'increase' ? (Number(r.amount) || 0) : -(Number(r.amount) || 0)), 0);
      const credit = Math.round((baseCredit + netAdjust) * 100) / 100;
      // 采购总额/已收货款一律走 paySummary 口径函数（与客户列表快照同源）：
      // 旧实现此处另写一套“全局账单是否为空”回退判断，与快照的逐客户回退不一致，
      // 且已收货款误读旧键名 customer_receipts_（无写入点）导致恒为 0 而虚报额度不足
      let totalPurchase = 0;
      let receivedPayment = 0;
      try {
        const idNameMap: Record<string, string> = {};
        allCustomers.forEach((r: any) => { if (r && r.id && r.name) idNameMap[String(r.id)] = String(r.name); });
        totalPurchase = toYuan(computeCustomerPurchaseCents(owner, customerName));
        receivedPayment = toYuan(computeCustomerReceivedCents(owner, customerName, idNameMap));
      } catch { /* ignore */ }
      return Math.round((credit - (totalPurchase - receivedPayment)) * 100) / 100;
    } catch { return null; }
  }, []);
