  // 从打印预览执行打印（组件级别，使用 printPreviewHtml 状态）
  const handleDoPrint = useCallback(() => {
    const iframe = document.createElement('iframe');
    iframe.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;';
    document.body.appendChild(iframe);
    const iframeDoc = iframe.contentWindow?.document;
    if (iframeDoc) {
      iframeDoc.open();
      iframeDoc.write(printPreviewHtml);
      iframeDoc.close();
      iframe.contentWindow?.focus();
      iframe.contentWindow?.print();
      // 打印后关闭所有预览窗口
      setTimeout(() => {
        document.body.removeChild(iframe);
        setPrintPreviewVisible(false);
        setPrintDialogVisible(false);
        // 采购申请单 BOM 打印后标记为“已打印”
        if (printDialogType === 'bom' && pageConfig?.title === '采购申请单' && selectedRowKeys.length > 0) {
          const owner = getDataOwner();
          const key = `pageData_production_purchase-requisition_${owner}`;
          try {
            let list: any[] = JSON.parse(localStorage.getItem(key) || '[]');
            if (Array.isArray(list)) {
              list = list.map((r: any) => selectedRowKeys.includes(r.key) ? { ...r, printStatus: '已打印' } : r);
              const json = JSON.stringify(list);
              localStorage.setItem(key, json);
              setDataSource(list);
            }
          } catch { /* ignore */ }
          message.success('打印完成，已标记为“已打印”');
        }
      }, 1000);
    } else {
      message.error('打印失败，请重试');
      document.body.removeChild(iframe);
    }
  }, [printPreviewHtml]);

