  const getPersonOptions = useCallback(() => {
    const options: { label: string; value: string }[] = [];
    const seen = new Set<string>();
    // 1. 读取本租户成员账号（租户隔离，避免混入其他租户账号）
    try {
      const users = loadTenantUsers();
      users.forEach((u: any) => {
        const name = u.contactPerson || u.companyName || u.username;
        if (name && !seen.has(name)) {
          seen.add(name);
          options.push({ label: name, value: name });
        }
      });
    } catch { /* ignore */ }
    // 2. 从账号管理列表读取（accounts_xxx）
    try {
      const owner = getDataOwner();
      const accounts = JSON.parse(localStorage.getItem('accounts_' + owner) || '[]');
      accounts.forEach((a: any) => {
        const name = a.displayName || a.person || a.username;
        if (name && !seen.has(name)) {
          seen.add(name);
          options.push({ label: name, value: name });
        }
      });
    } catch { /* ignore */ }
    // 3. 确保当前登录用户也在选项中
    const currentUser = getCurrentUserDisplayName();
    if (currentUser && !seen.has(currentUser)) {
      options.push({ label: currentUser, value: currentUser });
    }
    return options;
  }, [getCurrentUserDisplayName, getDataOwner]);

  // 计算单价：根据基础售价 + 优惠方式自动计算
  const calcUnitPrice = useCallback((basePrice: number, discountType: string, discountValue: number): number => {
    if (!basePrice && basePrice !== 0) return 0;
    let result = basePrice;
    if (discountType === '折扣') {
      result = basePrice * (discountValue / 10);
    } else if (discountType === '减价') {
      result = basePrice - discountValue;
    } else if (discountType === '加价') {
      result = basePrice + discountValue;
    }
    return Math.max(0, Number(result.toFixed(2)));
  }, []);

