  const SYSTEM_BRANDS = ['自主品牌', '代工品牌A', '代工品牌B', '代工品牌C', '合作品牌', '白牌', '定制品牌'];
  const SYSTEM_CATEGORIES = ['电子产品', '服装配件', '五金工具', '包装材料', '家居用品', '机械设备', '化工原料', '汽车零部件'];

  // 加载自定义标签/品牌
  useEffect(() => {
    if (!isProductList) return;
    const dataOwner = getDataOwner();
    try {
      const tags = JSON.parse(localStorage.getItem(`custom_product_tags_${dataOwner}`) || '[]');
      const brands = JSON.parse(localStorage.getItem(`custom_brands_${dataOwner}`) || '[]');
      const cats = JSON.parse(localStorage.getItem(`custom_categories_${dataOwner}`) || '[]');
      if (Array.isArray(tags)) setCustomTags(tags);
      if (Array.isArray(brands)) setCustomBrands(brands);
      if (Array.isArray(cats)) setCustomCategories(cats);
    } catch { /* ignore */ }
  }, [isProductList]);

  // 行内编辑状态
  const [editingCell, setEditingCell] = useState<{ recordKey: string; dataIndex: string; value: any } | null>(null);
  const editingCellRef = useRef(editingCell);
  editingCellRef.current = editingCell;
  const inlineInputRef = useRef<any>(null);

  // 供应商数据（从采购商供应商列表加载）
  const [supplierOptions, setSupplierOptions] = useState<{ id: string; supplierName: string; shortName: string }[]>([]);
  useEffect(() => {
    if (!isProductList) return;
    const dataOwner = getDataOwner();
    const key = 'purchaser_suppliers_' + dataOwner;
    try {
      const data = JSON.parse(localStorage.getItem(key) || '[]');
      setSupplierOptions(data.map((s: any) => ({
        id: s.id,
        supplierName: s.supplierName,
        shortName: s.shortName || '',
      })));
    } catch { /* ignore */ }
    // 监听 storage 变化，实时更新供应商列表
    const handleStorage = (e: StorageEvent) => {
      if (e.key === key) {
        try {
          const data = JSON.parse(e.newValue || '[]');
          setSupplierOptions(data.map((s: any) => ({
            id: s.id,
            supplierName: s.supplierName,
            shortName: s.shortName || '',
          })));
        } catch { /* ignore */ }
      }
    };
    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, [isProductList]);

  // 点击单元格进入编辑模式
  const handleCellClick = useCallback((record: Record<string, any>, dataIndex: string) => {
    if (!isProductList || isViewOnly) return;
    // 图片和链接列不走行内编辑
    const col = effectivePageConfig?.columns.find(c => c.dataIndex === dataIndex);
    if (!col || col.type === 'image' || col.type === 'link') return;
    // 供应商编号由供应商名称自动填充，不允许直接编辑
    if (dataIndex === 'supplierCode') {
      message.info('供应商编号由供应商名称自动填充（英文简称）');
      return;
    }
    // 款式编码点击打开详情弹窗
    if (dataIndex === 'styleCode') {
      handleOpenStyleDetail(record);
      return;
    }
    // 商品标签 → 打开标签选择弹窗
    if (dataIndex === 'productTags') { handleOpenTagModal(record, 'productTags'); return; }
    // 品牌 → 打开品牌选择弹窗
    if (dataIndex === 'brand') { handleOpenTagModal(record, 'brand'); return; }
    // 分类 → 打开分类选择弹窗
    if (dataIndex === 'category') { handleOpenTagModal(record, 'category'); return; }
    // PERM_V2 字段编辑：商品族字段无编辑权限时禁止行内编辑
    if (isProductList && !fieldEditOk(dataIndex)) {
      message.info('无该字段编辑权限');
      return;
    }
    // 创建人/创建时间/修改时间 → 不允许修改
    if (dataIndex === 'creator' || dataIndex === 'createdAt' || dataIndex === 'updatedAt') {
      message.info('该字段不可修改');
      return;
    }
    setEditingCell({ recordKey: record.key, dataIndex, value: record[dataIndex] });
    setTimeout(() => {
      if (inlineInputRef.current) {
        if (typeof inlineInputRef.current.focus === 'function') inlineInputRef.current.focus();
        else if (typeof inlineInputRef.current.select === 'function') inlineInputRef.current.select();
      }
    }, 50);
  }, [isProductList, isViewOnly, pageConfig]);

  // ============ 产品唯一性检查 ============
  const findUniqueFieldConflict = useCallback((productCode: string, barcode?: string, nationalCode?: string, excludeKey?: string): string | null => {
    const owner = getDataOwner();
    try {
      const products = JSON.parse(localStorage.getItem(`pageData_basic-data_product-list_${owner}`) || '[]');
      for (const p of products) {
        if (excludeKey && p.key === excludeKey) continue;
        if (productCode && p.productCode === productCode) return `商品编码“${productCode}”已存在`;
        if (barcode && p.barcode === barcode) return `条形码“${barcode}”已存在`;
        if (nationalCode && p.nationalCode === nationalCode) return `国标码“${nationalCode}”已存在`;
      }
    } catch { /* ignore */ }
    return null;
  }, [getDataOwner]);

  // ============ 客户选择弹窗 ============
  const openCustomerSelect = useCallback((mode: 'orderEdit' | 'billSearch' | 'pickFilter' = 'orderEdit') => {
    // 读取 客户管理-客户基础信息-客户列表 数据（直接客户 + 已绑定采购商）
    setCustomerSelectList(loadAllCustomersFromStorage());
    setCustomerSelectSearch('');
    setCustomerSelectMode(mode);
    setCustomerSelectVisible(true);
  }, []);

  const handleCustomerSelect = useCallback((customer: any) => {
    // 打单拣货搜索筛选模式：回填客户名称搜索框（点查询后生效）
    if (customerSelectMode === 'pickFilter') {
      const name = String(customer.name || '').trim();
      setPickFieldFilters(prev => ({ ...prev, customerName: name }));
      setCustomerSelectVisible(false);
      message.success(`已选择客户：${name}`);
      return;
    }
    // 账单明细搜索筛选模式：回填客户名称并立即应用筛选
    if (customerSelectMode === 'billSearch') {
      const name = String(customer.name || '').trim();
      setDynamicFilterValues(prev => ({ ...prev, '客户名称': name }));
      setAppliedDynamicFilters(prev => ({ ...prev, '客户名称': name }));
      setCustomerSelectVisible(false);
      message.success(`已选择客户：${name}`);
      return;
    }
    editForm.setFieldsValue({
      customerName: customer.name || '',
      customerAccount: customer.name || '',
      receiverName: customer.contact || '',
      receiverPhone: customer.phone || '',
      province: customer.province || '',
      city: customer.city || '',
      district: customer.district || '',
      receiverDetail: customer.address || customer.detailAddress || '',
    });
    setSelectedProvince(customer.province || '');
    setSelectedCity(customer.city || '');
    setSelectedDistrict(customer.district || '');
    setCustomerSelectVisible(false);
    message.success(`已选择客户：${customer.name}`);
  }, [editForm, customerSelectMode]);

  // ============ 省市区级联选择 ============
  const provinceOptions = Object.keys(CHINA_REGIONS).map(p => ({ label: p, value: p }));
  const getCityOptions = useCallback((province: string) => {
    if (!province || !CHINA_REGIONS[province]) return [];
    return Object.keys(CHINA_REGIONS[province]).map(c => ({ label: c, value: c }));
  }, []);
  const getDistrictOptions = useCallback((province: string, city: string) => {
    if (!province || !city || !CHINA_REGIONS[province] || !CHINA_REGIONS[province][city]) return [];
    return CHINA_REGIONS[province][city].map(d => ({ label: d, value: d }));
  }, []);
  const handleProvinceChange = useCallback((val: string) => {
    setSelectedProvince(val);
    setSelectedCity('');
    setSelectedDistrict('');
    editForm.setFieldsValue({ province: val, city: '', district: '' });
  }, [editForm]);
  const handleCityChange = useCallback((val: string) => {
    setSelectedCity(val);
    setSelectedDistrict('');
    editForm.setFieldsValue({ city: val, district: '' });
  }, [editForm]);
  const handleDistrictChange = useCallback((val: string) => {
    setSelectedDistrict(val);
    editForm.setFieldsValue({ district: val });
  }, [editForm]);

  // ============ 新增订单省市区级联选择 ============
  const handleAddProvinceChange = useCallback((val: string) => {
    setAddSelectedProvince(val);
    setAddSelectedCity('');
    setAddSelectedDistrict('');
    addForm.setFieldsValue({ province: val, city: '', district: '' });
  }, [addForm]);
  const handleAddCityChange = useCallback((val: string) => {
    setAddSelectedCity(val);
    setAddSelectedDistrict('');
    addForm.setFieldsValue({ city: val, district: '' });
  }, [addForm]);
  const handleAddDistrictChange = useCallback((val: string) => {
    setAddSelectedDistrict(val);
    addForm.setFieldsValue({ district: val });
  }, [addForm]);

  // ============ 卖家备注图片上传（按顺序填充，满5张提醒） ============
  const handleSellerImagePaste = useCallback((e: React.ClipboardEvent) => {
    const items = e.clipboardData?.items;
    if (!items) return;
    const arr = Array.from(items);
    for (let i = 0; i < arr.length; i++) {
      const item = arr[i];
      if (item.type.startsWith('image/')) {
        const blob = item.getAsFile();
        if (!blob) continue;
        const slot = [...sellerImages]; while (slot.length < 5) slot.push('');
        const target = slot.findIndex(s => !s);
        if (target === -1) { message.warning('备注图片已满（最多5张），请先删除后再上传'); return; }
        compressImageFile(blob).then(dataUrl => {
          setSellerImages(prev => { const n = [...prev]; while (n.length < 5) n.push(''); n[target] = dataUrl; return n; });
        }).catch(() => message.error('图片处理失败'));
        break;
      }
    }
  }, [sellerImages]);

  const handleSellerImageClick = useCallback(() => {
    const slot = [...sellerImages]; while (slot.length < 5) slot.push('');
    const target = slot.findIndex(s => !s);
    if (target === -1) { message.warning('备注图片已满（最多5张），请先删除后再上传'); return; }
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;
      compressImageFile(file).then(dataUrl => {
        setSellerImages(prev => { const n = [...prev]; while (n.length < 5) n.push(''); n[target] = dataUrl; return n; });
      }).catch(() => message.error('图片处理失败'));
    };
    input.click();
  }, [sellerImages]);

  // 保存行内编辑（使用 ref 避免闭包问题）
  const handleInlineEditSave = useCallback(() => {
    const cell = editingCellRef.current;
    if (!cell) return;
    const { recordKey, dataIndex, value } = cell;
    // 唯一性检查：商品编码、国标码
    if (dataIndex === 'productCode' || dataIndex === 'nationalCode') {
      const record = dataSource.find(r => r.key === recordKey);
      if (!record) return;
      const pc = dataIndex === 'productCode' ? String(value || '').trim() : String(record.productCode || '').trim();
      const nc = dataIndex === 'nationalCode' ? String(value || '').trim() : String(record.nationalCode || '').trim();
      const conflict = findUniqueFieldConflict(pc, undefined, nc, recordKey);
      if (conflict) { message.error(conflict); setEditingCell(null); return; }
    }
    setDataSource(prev => prev.map(item => {
      if (item.key !== recordKey) return item;
      const updated = { ...item, [dataIndex]: value };
      // 同步关联字段
      if (dataIndex === 'productCode') updated.id = value;
      if (dataIndex === 'suggestedPrice') updated.amount = Number(value) || 0;
      if (dataIndex === 'actualStock') updated.quantity = Number(value) || 0;
      // 供应商名称 → 自动填充供应商编号（英文简称）
      if (dataIndex === 'supplierName') {
        const matchedSupplier = supplierOptions.find(s => s.supplierName === value);
        updated.supplierCode = matchedSupplier?.shortName || '';
      }
      return updated;
    }));
    setEditingCell(null);
    message.success('已保存修改');
  }, [supplierOptions, dataSource, findUniqueFieldConflict]);

  // 取消行内编辑
  const handleInlineEditCancel = useCallback(() => {
    setEditingCell(null);
  }, []);

  // 行内编辑键盘事件
  const handleInlineEditKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleInlineEditSave();
    } else if (e.key === 'Escape') {
      handleInlineEditCancel();
    }
  }, [handleInlineEditSave, handleInlineEditCancel]);

  // 点击外部关闭行内编辑
  useEffect(() => {
    if (!editingCell) return;
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      // 点击在行内编辑单元格内部，忽略
      if (target.closest('.inline-edit-cell')) return;
      // 点击在 antd Select/Dropdown 下拉弹出层内，忽略（让 onChange 先触发）
      if (target.closest('.ant-select-dropdown') || target.closest('.ant-dropdown') || target.closest('.ant-popover')) return;
      // 延迟保存，确保 Select onChange 的状态更新已生效
      setTimeout(() => handleInlineEditSave(), 50);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [editingCell, handleInlineEditSave]);

  // 渲染行内编辑单元格
  const renderEditableCell = (col: any, val: any, record: Record<string, any>, content: React.ReactNode) => {
    if (!isProductList) return content;
    if (col.type === 'image' || col.type === 'link') return content;
    // 可配货库存为计算字段，不允许行内编辑
    if (col.dataIndex === 'allocatableStock') return content;
    // 订单占用数为计算字段，不允许行内编辑
    if (col.dataIndex === 'orderReserved') return content;
    // 实际库存数点击弹出库存变化明细，不允许行内编辑
    if (col.dataIndex === 'actualStock') return content;

    const isEditing = editingCell?.recordKey === record.key && editingCell?.dataIndex === col.dataIndex;

    if (isEditing) {
      return (
        <div className="inline-edit-cell" style={{ margin: '-4px -8px' }} onClick={(e) => e.stopPropagation()}>
          {(col.type === 'number' || col.type === 'money' || col.type === 'rate') ? (
            <Input
              ref={inlineInputRef as any}
              type="number"
              value={editingCell?.value ?? ''}
              onChange={(e) => setEditingCell(prev => prev ? { ...prev, value: e.target.value } : null)}
              onKeyDown={handleInlineEditKeyDown}
              onBlur={handleInlineEditSave}
              style={{ width: '100%', border: 'none', borderBottom: `2px solid ${PRIMARY}`, borderRadius: 0, background: 'transparent' }}
              size="small"
            />
          ) : col.type === 'tag' && (col.dataIndex === 'status' || col.dataIndex === 'productStatus') ? (
            <Select
              ref={inlineInputRef as any}
              value={editingCell?.value}
              onChange={(v) => { setEditingCell(prev => prev ? { ...prev, value: v } : null); }}
              onBlur={handleInlineEditSave}
              autoFocus
              style={{ width: '100%' }}
              size="small"
              options={[
                { label: '在售', value: '在售' },
                { label: '开发', value: '开发' },
                { label: '预售', value: '预售' },
                { label: '停产', value: '停产' },
              ]}
            />
          ) : col.dataIndex === 'productType' ? (
            <Select
              ref={inlineInputRef as any}
              value={editingCell?.value}
              onChange={(v) => { setEditingCell(prev => prev ? { ...prev, value: v } : null); }}
              onBlur={handleInlineEditSave}
              autoFocus
              style={{ width: '100%' }}
              size="small"
              options={[
                { label: '成品', value: '成品' },
                { label: '半成品', value: '半成品' },
                { label: '原材料', value: '原材料' },
              ]}
            />
          ) : col.dataIndex === 'level' ? (
            <InputNumber
              ref={inlineInputRef as any}
              value={editingCell?.value}
              onChange={(v) => { setEditingCell(prev => prev ? { ...prev, value: v } : null); }}
              onBlur={handleInlineEditSave}
              autoFocus
              style={{ width: '100%' }}
              size="small"
              min={1}
              max={99}
            />
          ) : col.dataIndex === 'supplierName' ? (
            <Select
              ref={inlineInputRef as any}
              value={editingCell?.value}
              onChange={(v) => { setEditingCell(prev => prev ? { ...prev, value: v } : null); }}
              onBlur={handleInlineEditSave}
              autoFocus
              showSearch
              allowClear
              placeholder="选择供应商"
              style={{ width: '100%', minWidth: 160 }}
              size="small"
              filterOption={(input, option) =>
                (option?.label as string || '').toLowerCase().includes(input.toLowerCase())
              }
              options={[
                ...supplierOptions.map(s => ({
                  label: s.supplierName,
                  value: s.supplierName,
                })),
                ...(supplierOptions.length === 0 ? [] : [{ label: '— 无供应商 —', value: '' }]),
              ]}
            />
          ) : col.type === 'boolean' ? (
            <Select
              ref={inlineInputRef as any}
              value={editingCell?.value}
              onChange={(v) => { setEditingCell(prev => prev ? { ...prev, value: v } : null); }}
              onBlur={handleInlineEditSave}
              autoFocus
              style={{ width: '100%' }}
              size="small"
              options={[
                { label: '已同步', value: true },
                { label: '未同步', value: false },
              ]}
            />
          ) : (
            <Input
              ref={inlineInputRef as any}
              value={editingCell?.value ?? ''}
              onChange={(e) => setEditingCell(prev => prev ? { ...prev, value: e.target.value } : null)}
              onKeyDown={handleInlineEditKeyDown}
              onBlur={handleInlineEditSave}
              style={{ width: '100%', border: 'none', borderBottom: `2px solid ${PRIMARY}`, borderRadius: 0, background: 'transparent' }}
              size="small"
            />
          )}
        </div>
      );
    }

    // 非编辑状态：悬停显示可编辑提示
    return (
      <div
        onClick={(e) => { e.stopPropagation(); handleCellClick(record, col.dataIndex); }}
        style={{ cursor: 'pointer', padding: '2px 4px', borderRadius: 3, transition: 'background 0.2s', minHeight: 22 }}
        onMouseEnter={(e) => { (e.currentTarget as HTMLElement).style.background = '#e6f4ff'; }}
        onMouseLeave={(e) => { (e.currentTarget as HTMLElement).style.background = 'transparent'; }}
      >
        {content}
      </div>
    );
  };

  // 导入必填字段（与模板标注、解析校验一致）：商品编码通用必填；成品另需款式编码/基础售价；原材料另需款式编码/供应商/成本价/单位
  const getImportRequiredFields = useCallback((): Set<string> => {
    const s = new Set(['productCode']);
    const t = pageConfig?.productTypeFilter;
    if (t === '成品') ['styleCode', 'suggestedPrice', 'supplierName'].forEach(f => s.add(f));
    else if (t === '原材料') ['styleCode', 'supplierName', 'costPrice', 'unit'].forEach(f => s.add(f));
    return s;
  }, [pageConfig]);

  // 文件列未覆盖的必填字段（预览步骤红色警示，并阻止确认导入）
  const importMissingRequired = useMemo(() => {
    const mapped = new Set(importMapping.filter(m => m.dataIndex).map(m => m.dataIndex as string));
    return Array.from(getImportRequiredFields()).filter(k => !mapped.has(k))
      .map(k => effectivePageConfig?.columns.find(c => c.dataIndex === k)?.title || k);
  }, [importMapping, getImportRequiredFields, effectivePageConfig]);

  // 下载导入模板
  const handleDownloadTemplate = useCallback(() => {
    if (!effectivePageConfig?.columns) return;
    // 使用所有列（排除操作列和特殊列）
    const cols = effectivePageConfig.columns.filter(c => c.key !== 'actions');
    const productTypeFilter = pageConfig?.productTypeFilter;
    const requiredFields = getImportRequiredFields();
    const headers = cols.map(c => {
      const isRequired = requiredFields.has(c.key);
      return isRequired ? `${c.title}（必填）` : c.title;
    });
    const sampleRow = cols.map(c => {
      if (c.key === 'productCode') return 'SKU100001';
      if (c.key === 'styleCode') return 'SK2024001';
      if (c.key === 'nationalCode') return 'GB6900001';
      if (c.key === 'suggestedPrice') return 99.99;
      if (c.key === 'costPrice') return 50.00;
      if (c.key === 'actualStock') return 100;
      if (c.key === 'orderReserved') return 10;
      if (c.key === 'productStatus') return '在售';
      if (c.key === 'brand') return '自主品牌';
      if (c.key === 'category') return '电子产品';
      if (c.key === 'color') return '黑色';
      if (c.key === 'spec') return '标准';
      if (c.key === 'unit') return '个';
      if (c.key === 'level') return 1;
      if (c.key === 'supplierName') return '示例供应商';
      return '';
    });
    const ws = XLSX.utils.aoa_to_sheet([headers, sampleRow]);
    // 设置列宽
    ws['!cols'] = cols.map(c => ({ wch: Math.max(c.width ? c.width / 8 : 12, 10) }));
    // 为必填字段表头添加红色背景
    cols.forEach((c, idx) => {
      if (requiredFields.has(c.key)) {
        const cellRef = XLSX.utils.encode_cell({ r: 0, c: idx });
        if (ws[cellRef]) {
          ws[cellRef].s = {
            fill: { fgColor: { rgb: 'FFCCCC' } },
            font: { bold: true, color: { rgb: 'CC0000' } },
          };
        }
      }
    });
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, '产品导入模板');
    XLSX.writeFile(wb, `产品导入模板_${productTypeFilter || '产品'}_${new Date().toLocaleDateString('zh-CN')}.xlsx`);
    message.success('模板已下载，红色标记字段为必填项');
  }, [pageConfig, getImportRequiredFields]);

  // 解析导入文件
  const handleImportFile = useCallback((file: File) => {
    setImportFile(file);
    setImportErrors([]);
    setImportPreviewData([]);
    setImportResult(null);

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        // 部分旧系统导出的 xlsx 为 zip64 容器，SheetJS 内置解压不支持（抛超长字符串异常），
        // 回退：fflate 解包后以 store 模式重打包为标准 zip 再交给 SheetJS 解析
        let wb: XLSX.WorkBook;
        try {
          wb = XLSX.read(data, { type: 'array' });
        } catch {
          wb = XLSX.read(zipSync(unzipSync(data), { level: 0 }), { type: 'array' });
        }
        const ws = wb.Sheets[wb.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json<Record<string, any>>(ws, { defval: '' });

        if (jsonData.length === 0) {
          message.warning('文件中没有数据');
          return;
        }

        // 构建标题到 dataIndex 的映射
        const titleToKey: Record<string, string> = {};
        effectivePageConfig?.columns.forEach(c => {
          titleToKey[c.title] = c.dataIndex;
        });
        // 额外添加一些常用别名
        titleToKey['产品名称'] = 'name';
        titleToKey['产品编码'] = 'id';
        // 兼容旧系统导出的表头（商品资料导出文件）
        titleToKey['基本售价'] = 'suggestedPrice';
        titleToKey['订单占有数'] = 'orderReserved';
        titleToKey['商品属性'] = 'productType';
        // 兼容模板表头：剥离“（必填）”后缀后再匹配（模板下载的必填列带此后缀）
        const resolveHeaderKey = (h: string) => {
          const t = String(h).trim();
          return titleToKey[t.replace(/（必填）$/, '')] || titleToKey[t] || null;
        };

        // 字段匹配情况：文件列 → 系统字段（未匹配列将被忽略），预览步骤展示
        const requiredFields = getImportRequiredFields();
        setImportMapping(Object.keys(jsonData[0] || {}).map(h => {
          const key = resolveHeaderKey(h);
          const col = key ? effectivePageConfig?.columns.find(c => c.dataIndex === key) : null;
          return { header: String(h), dataIndex: key, title: col?.title || null, required: !!key && requiredFields.has(key) };
        }));

        const errors: { row: number; field: string; message: string }[] = [];
        const parsedRows: Record<string, any>[] = [];

        jsonData.forEach((row, idx) => {
          const mapped: Record<string, any> = {};
          Object.entries(row).forEach(([header, value]) => {
            const key = resolveHeaderKey(header);
            if (key) {
              mapped[key] = value;
            }
          });
          mapped.key = `import-${Date.now()}-${idx}`;

          // 验证必填字段
          if (!mapped.productCode || String(mapped.productCode).trim() === '') {
            errors.push({ row: idx + 2, field: '商品编码', message: '商品编码不能为空' });
          }
          // 成品导入时的额外必填字段验证
          if (pageConfig?.productTypeFilter === '成品') {
            if (!mapped.styleCode || String(mapped.styleCode).trim() === '') {
              errors.push({ row: idx + 2, field: '款式编码', message: '款式编码不能为空' });
            }
            if (!mapped.supplierName || String(mapped.supplierName).trim() === '') {
              errors.push({ row: idx + 2, field: '供应商名称', message: '供应商不能为空' });
            }
            if (mapped.suggestedPrice === undefined || mapped.suggestedPrice === '' || mapped.suggestedPrice === null) {
              errors.push({ row: idx + 2, field: '基础售价', message: '基础售价不能为空' });
            }
          }
          // 原材料导入时的额外必填字段验证
          if (pageConfig?.productTypeFilter === '原材料') {
            if (!mapped.styleCode || String(mapped.styleCode).trim() === '') {
              errors.push({ row: idx + 2, field: '款式编码', message: '款式编码不能为空' });
            }
            if (!mapped.supplierName || String(mapped.supplierName).trim() === '') {
              errors.push({ row: idx + 2, field: '供应商名称', message: '供应商不能为空' });
            }
            if (mapped.costPrice === undefined || mapped.costPrice === '' || mapped.costPrice === null) {
              errors.push({ row: idx + 2, field: '成本价', message: '成本价不能为空' });
            }
            if (!mapped.unit || String(mapped.unit).trim() === '') {
              errors.push({ row: idx + 2, field: '单位', message: '单位不能为空' });
            }
          }

          // 数值字段转换
          ['suggestedPrice', 'costPrice', 'otherPrice1', 'actualStock', 'orderReserved',
           'pendingShip', 'stockLower', 'stockUpper', 'stdBoxQty', 'weightKg',
           'yesterdaySales', 'yesterdayShipped', 'yesterdayReturns',
           'week7Sales', 'week7Shipped', 'week7Returns',
           'day15Sales', 'day15Shipped', 'day15Returns'].forEach(field => {
            if (mapped[field] !== undefined && mapped[field] !== '') {
              mapped[field] = Number(mapped[field]) || 0;
            }
          });

          // 布尔字段转换
          if (mapped.stockSync !== undefined) {
            mapped.stockSync = mapped.stockSync === '已同步' || mapped.stockSync === '开启' || mapped.stockSync === true || mapped.stockSync === 1;
          }
          // 旧系统导出的商品状态取值归一化
          if (mapped.productStatus === '启用') mapped.productStatus = '在售';

          // 设置默认值
          if (!mapped.productStatus) mapped.productStatus = '在售';
          if (!mapped.status) mapped.status = 'processing';
          if (!mapped.creator) mapped.creator = getCurrentUserDisplayName();
          mapped.availableStock = (Number(mapped.actualStock) || 0) - (Number(mapped.orderReserved) || 0);
          mapped.createdAt = mapped.createdAt || new Date().toLocaleDateString('zh-CN').replace(/\//g, '-');
          mapped.updatedAt = new Date().toLocaleDateString('zh-CN').replace(/\//g, '-');

          parsedRows.push(mapped);
        });

        setImportPreviewData(parsedRows);
        setImportErrors(errors);
        setImportStep(1);
      } catch (err) {
        message.error('文件解析失败，请确认文件格式为 Excel (.xlsx/.xls)');
      }
    };
    reader.readAsArrayBuffer(file);
    return false; // prevent default upload
  }, [pageConfig, effectivePageConfig, getImportRequiredFields]);

  // 验证并执行导入（分块执行 + 实时进度展示）
  const handleImportConfirm = useCallback(async () => {
    if (importPreviewData.length === 0 || importProgress.running) return;
    const typeFilter = pageConfig?.productTypeFilter;
    const errors: { row: number; field: string; message: string }[] = [...importErrors];
    const total = importPreviewData.length;
    const tick = () => new Promise<void>(r => setTimeout(r, 0));
    setImportProgress({ running: true, done: 0, total });

    // 检查导入数据内部的重复
    const codeSet = new Set<string>();
    const nationalSet = new Set<string>();
    importPreviewData.forEach((row, idx) => {
      const pc = String(row.productCode || '').trim();
      const nc = String(row.nationalCode || '').trim();
      if (pc && codeSet.has(pc)) {
        errors.push({ row: idx + 2, field: '商品编码', message: `导入数据中商品编码 "${pc}" 重复` });
      }
      codeSet.add(pc);
      if (nc && nationalSet.has(nc)) {
        errors.push({ row: idx + 2, field: '国标码', message: `导入数据中国标码 "${nc}" 重复` });
      }
      if (nc) nationalSet.add(nc);
    });

    // 检查与现有数据的重复
    const existingCodes = new Set(dataSource.map(d => String(d.productCode || '').trim()).filter(Boolean));
    const existingNationals = new Set(dataSource.map(d => String(d.nationalCode || '').trim()).filter(Boolean));

    // 自动创建不存在的供应商
    const existingSupplierNames = new Set(supplierOptions.map(s => s.supplierName));
    const newSuppliers: { id: string; supplierName: string; shortName: string }[] = [];
    importPreviewData.forEach(row => {
      const sn = String(row.supplierName || '').trim();
      if (sn && !existingSupplierNames.has(sn) && !newSuppliers.some(s => s.supplierName === sn)) {
        newSuppliers.push({
          id: `SUP-${String(Date.now()).slice(-8)}-${newSuppliers.length}`,
          supplierName: sn,
          shortName: sn.length >= 4 ? sn.slice(0, 4) : sn,
        });
        existingSupplierNames.add(sn);
      }
    });
    if (newSuppliers.length > 0) {
      const dataOwner = getDataOwner();
      const supplierKey = 'purchaser_suppliers_' + dataOwner;
      try {
        const current = JSON.parse(localStorage.getItem(supplierKey) || '[]');
        localStorage.setItem(supplierKey, JSON.stringify([...current, ...newSuppliers]));
        setSupplierOptions(prev => [...prev, ...newSuppliers]);
        message.success(`已自动创建 ${newSuppliers.length} 个新供应商：${newSuppliers.map(s => s.supplierName).join('、')}`);
      } catch { /* ignore */ }
    }

    let added = 0;
    let updated = 0;
    let skipped = 0;
    // 新增行统一补齐默认字段（与单条新增口径一致）
    const prepareNewRow = (row: Record<string, any>, idx: number) => {
      row.id = row.id || `PRD-${String(Date.now()).slice(-8)}-${idx}`;
      row.name = row.name || row.shortName || `产品-${String(row.productCode || '').trim()}`;
      row.amount = row.suggestedPrice || 0;
      row.quantity = row.actualStock || 0;
      row.date = row.createdAt;
      row.person = row.creator;
      row.dept = row.dept || '仓储部';
      row.progress = 0;
      row.passRate = '';
      row.deliveryDays = 0;
      row.margin = '';
      // 子页面导入时自动设置产品种类
      if (typeFilter && !row.productType) row.productType = typeFilter;
    };

    if (importMode === 'add') {
      // 新增模式：商品编码/国标码已存在或校验错误的行跳过，逐行分块上报进度
      const validRows: Record<string, any>[] = [];
      for (let idx = 0; idx < total; idx++) {
        const row = importPreviewData[idx];
        const pc = String(row.productCode || '').trim();
        const nc = String(row.nationalCode || '').trim();
        if (errors.some(e => e.row === idx + 2)) {
          skipped++;
        } else if (pc && existingCodes.has(pc)) {
          errors.push({ row: idx + 2, field: '商品编码', message: `商品编码 "${pc}" 已存在，新增失败` });
          skipped++;
        } else if (nc && existingNationals.has(nc)) {
          errors.push({ row: idx + 2, field: '国标码', message: `国标码 "${nc}" 已存在，新增失败` });
          skipped++;
        } else {
          prepareNewRow(row, idx);
          validRows.push(row);
          added++;
        }
        if ((idx + 1) % 20 === 0 || idx === total - 1) {
          setImportProgress({ running: true, done: idx + 1, total });
          await tick();
        }
      }
      if (validRows.length > 0) setDataSource(prev => [...validRows, ...prev]);
    } else {
      // 更新模式：以商品编码匹配，逐行分块上报进度
      const updateMap = new Map<string, Record<string, any>>();
      for (let idx = 0; idx < total; idx++) {
        const row = importPreviewData[idx];
        const pc = String(row.productCode || '').trim();
        const nc = String(row.nationalCode || '').trim();
        if (importErrors.some(e => e.row === idx + 2)) {
          skipped++;
        } else if (nc && dataSource.some(d =>
          String(d.nationalCode || '').trim() === nc &&
          String(d.productCode || '').trim() !== pc
        )) {
          const conflict = dataSource.find(d => String(d.nationalCode || '').trim() === nc);
          errors.push({ row: idx + 2, field: '国标码', message: `国标码 "${nc}" 已被商品编码 "${conflict?.productCode}" 使用` });
          skipped++;
        } else if (nc && importPreviewData.some((r, ridx) =>
          ridx !== idx &&
          String(r.nationalCode || '').trim() === nc &&
          String(r.productCode || '').trim() !== pc
        )) {
          errors.push({ row: idx + 2, field: '国标码', message: `国标码 "${nc}" 与导入中其他记录冲突` });
          skipped++;
        } else {
          updateMap.set(pc, row);
        }
        if ((idx + 1) % 20 === 0 || idx === total - 1) {
          setImportProgress({ running: true, done: idx + 1, total });
          await tick();
        }
      }
      // 匹配到已有记录的更新；商品编码不存在的转新增
      const newRows: Record<string, any>[] = [];
      updateMap.forEach((row, pc) => {
        if (existingCodes.has(pc)) {
          updated++;
        } else {
          prepareNewRow(row, importPreviewData.indexOf(row));
          newRows.push(row);
          updateMap.delete(pc);
          added++;
        }
      });
      if (updateMap.size > 0) {
        setDataSource(prev => prev.map(item => {
          const m = updateMap.get(String(item.productCode || '').trim());
          return m ? { ...item, ...m, key: item.key } : item;
        }));
      }
      if (newRows.length > 0) setDataSource(prev => [...newRows, ...prev]);
    }

    setImportErrors(errors);
    setImportProgress({ running: false, done: total, total });
    setImportResult({ added, updated, skipped });
    setImportStep(2);
  }, [importPreviewData, importErrors, importMode, dataSource, pageConfig, supplierOptions, getDataOwner, importProgress.running]);

  // 重置导入状态
  const resetImport = useCallback(() => {
    setImportVisible(false);
    setImportStep(0);
    setImportFile(null);
    setImportPreviewData([]);
    setImportErrors([]);
    setImportResult(null);
    setImportMapping([]);
    setImportProgress({ running: false, done: 0, total: 0 });
  }, []);

  // ============ 账单明细（客户管理）：基于订单生成账单行 ============
  const buildBillDetailRows = useCallback((existing: Record<string, any>[]) => {
    const owner = getDataOwner();
    let orders: Record<string, any>[] = [];
    try { orders = JSON.parse(localStorage.getItem(`pageData_sales_order-manage_${owner}`) || '[]'); } catch { /* ignore */ }
    if (!Array.isArray(orders)) orders = [];
    const existMap = new Map(existing.map(r => [r.id, r]));
    // 发货凭证：已有出库单的订单视同已发货（部分发货路径仅生成出库单未改状态），
    // 保证余额支付订单发货后账单明细必然生成账单行
    const outboundOrderIds = new Set<string>();
    try {
      const so: any[] = JSON.parse(localStorage.getItem(`sales_outbound_${owner}`) || '[]');
      (Array.isArray(so) ? so : []).forEach((s: any) => { if (s?.orderId) outboundOrderIds.add(String(s.orderId)); });
    } catch { /* ignore */ }
    // 存量行全量保留（防擦除不变量）：凡不在订单集合中的已有行（手工新增/退货登记/历史行）一律保留在列表顶部。
    // 不能只保留 _manual 行——否则订单键暂缺（未拉取/owner 不一致）时重建会把订单派生行与历史行全部丢弃并上传擦除。
    const orderIds = new Set(orders.map((o: any) => o.id));
    const preservedRows = existing.filter((r: any) => r && r.id && !orderIds.has(r.id));
    // 凭证映射一次解析：重建时为缺凭证的账单行补账号+公司编号（第一阶段铺垫，不改匹配逻辑）
    const credMap = buildCompanyCredMap();
    return [...preservedRows, ...orders
      .filter((o: any) => o && o.id && (o.orderStatus === '已发货' || o.orderStatus === '已完成' || outboundOrderIds.has(String(o.id))) && (o.payMethod === '余额支付' || String(o.orderTags || '').includes('余额支付') || String(o.orderTag || '').includes('余额支付')))
      .sort((a: any, b: any) => String(b.createTime || '').localeCompare(String(a.createTime || '')))
      .map((o: any) => {
        const prev = existMap.get(o.id);
        // 客户编辑保护：重建时保留编辑弹窗人工改过的客户（按改名链折叠后仍不同源才视为人工改客户），
        // 并携带对手方凭据/辅助单号等回填字段，避免刷新后客户名称与匹配凭据丢失
        const orderName = String(o.customerName || '');
        const prevName = String(prev?.customerName || '');
        const editedCust = !!prev && !!prevName && prevName !== orderName &&
          resolveLatestCompanyName(prevName, '') !== resolveLatestCompanyName(orderName, '');
        const custName = editedCust ? prevName : (orderName || prevName);
        const rowCred = resolveCompanyCred(custName, credMap);
        let items: any[] = [];
        try { if (o.orderItems) items = JSON.parse(o.orderItems); } catch { /* ignore */ }
        // 兼容历史推送订单：orderItems 中单价字段名为 unitPrice，统一映射为 price
        items = items.map((it: any) => ({ ...it, price: it.price ?? it.unitPrice ?? 0 }));
        // 已入账终态行（对账完成/确认无误/按采方入账）：金额与明细锁定在对账时的数字，不被订单侧
        // 改写（取消/反取消/缺货拆分/拆分合并/编辑弹窗回算）覆盖；订单当前值与锁定值有差额时
        // 只挂 _orderDiff 标记供列表提示（旧实现只冻结「按采方入账」，另两个终态会被静默改数）
        const af = resolveBillAmountFields(prev, {
          totalCount: Number(o.palletCount) || items.reduce((s: number, it: any) => s + (Number(it.quantity) || 0), 0),
          productDetail: o.productDetail || items.map((it: any) => `${it.productCode || ''}×${Number(it.quantity) || 0}`).join('，'),
          totalAmount: Number(o.productAmount) || 0,
          paidAmount: Number(o.paidAmount) || 0,
          items,
        });
        const rowItems = af.items;
        const digits = String(o.id || '').replace(/\D/g, '').slice(-6);
        return {
          key: prev?.key || `bill-${o.id}`,
          id: o.id,
          outboundNo: o.outboundNo || prev?.outboundNo || (digits ? `CK-${digits}` : ''),
          customerName: custName,
          customerUsername: prev?.customerUsername || o.customerUsername || rowCred?.username || '',
          customerNo: prev?.customerNo || o.customerNo || rowCred?.companyNo || '',
          auxDocNo: prev?.auxDocNo || '',
          // 人工改客户标记随重建保留，名称自愈持续跳过该行客户名改写
          ...(prev?._custEdited ? { _custEdited: true } : {}),
          // 订单金额漂移标记：仅在终态行且订单值≠锁定值时写入，否则不残留旧标记
          ...(af._orderDiff !== undefined ? { _orderAmount: af._orderAmount, _orderDiff: af._orderDiff } : {}),
          outboundDate: normBillDay(prev?.outboundDate || o.payTime || o.createTime),
          createdAt: prev?.createdAt || o.payTime || o.createTime || '',
          totalCount: af.totalCount,
          productDetail: af.productDetail,
          totalAmount: af.totalAmount,
          paidAmount: af.paidAmount,
          billSource: '订单',
          orderStatus: o.auditStatus === '已取消' ? '已取消' : (o.orderStatus || ''),
          reconResult: prev?.reconResult || '待对账',
          diffDesc: prev?.diffDesc || '',
          supplierReconPerson: prev?.supplierReconPerson || '',
          purchaserReconPerson: prev?.purchaserReconPerson || '',
          confirmTime: prev?.confirmTime || '',
          items: rowItems,
          // 备注图片仅存于账单行自身（非订单字段），重建时必须从旧行带回，否则刷新后丢失
          image: prev?.image || '',
        };
      })];
  }, [getDataOwner]);

  // 实际库存自愈：stock_change_log 为库存变动唯一真值源（入库/出库/盘点均经 updateProductStock 记日志），
  // 取每商品最新一条 afterStock 校正 actualStock，纠正跨端同步/内存回写带来的陈旧副本（实际库存归 0/跳变根因）
  const healActualStockFromLogs = useCallback((rows: Record<string, any>[]) => {
    if (!Array.isArray(rows) || rows.length === 0) return rows;
    let logs: any[] = [];
    try { logs = JSON.parse(localStorage.getItem(`stock_change_log_${getDataOwner()}`) || '[]'); } catch { logs = []; }
    if (!Array.isArray(logs) || logs.length === 0) return rows;
    const tsOf = (t: any) => Date.parse(String(t || '').replace(/-/g, '/')) || 0;
    const latest = new Map<string, number>();
    logs.slice().sort((a: any, b: any) => tsOf(a?.createTime) - tsOf(b?.createTime)).forEach((l: any) => {
      if (!l?.productCode || l.afterStock === undefined || l.afterStock === null || l.afterStock === '') return;
      latest.set(String(l.productCode), Number(l.afterStock) || 0);
    });
    if (latest.size === 0) return rows;
    let changed = false;
    const next = rows.map((r: any) => {
      const code = String(r?.productCode || '');
      if (!code || !latest.has(code)) return r;
      const v = latest.get(code) as number;
      if ((Number(r.actualStock) || 0) !== v) { changed = true; return { ...r, actualStock: v }; }
      return r;
    });
    return changed ? next : rows;
  }, [getDataOwner]);

  // 发货后重建账单明细落库：仅已发货/已完成订单生成「订单」来源账单，立即持久化（取消手工新增后账单唯一来源）
  const refreshBillDetailStorage = useCallback((owner: string) => {
    try {
      const storageKey = `pageData_customer_bill-detail_${owner}`;
      let existing: Record<string, any>[] = [];
      try { existing = JSON.parse(localStorage.getItem(storageKey) || '[]'); } catch { existing = []; }
      if (!Array.isArray(existing)) existing = [];
      const next = buildBillDetailRows(existing);
      safeSetItem(storageKey, JSON.stringify(next));
    } catch { /* ignore */ }
  }, [buildBillDetailRows]);

  // ============ 退货登记（账单明细）：负数退货行 + 镜像同步采购商平台 + 库存出入库联动 ============
  const [returnRegVisible, setReturnRegVisible] = useState(false);
  const returnRegCounterpartyOptions = useMemo(() => {
    if (!returnRegVisible) return [];
    // 仅当前租户的对应采购商：已绑定采购商（boundPurchasers_<owner>，带明确账号）优先，
    // 再补本租户账单明细/客户信息中出现的客户（同名账号用绑定关系消歧，唯一公司名直接命中）
    const owner = getDataOwner();
    const out: { value: string; label: string }[] = [];
    const seen = new Set<string>();
    const push = (un: string, label: string) => {
      if (!un || !label || seen.has(un)) return;
      seen.add(un);
      out.push({ value: un, label });
    };
    try {
      const bound: any[] = JSON.parse(localStorage.getItem(`boundPurchasers_${owner}`) || '[]');
      bound.forEach((bp: any) => push(String(bp.purchaserUsername || ''), String(bp.purchaserName || bp.purchaserUsername || '')));
    } catch { /* ignore */ }
    const names = new Set<string>();
    dataSource.forEach((r: any) => { if (r && r.customerName) names.add(String(r.customerName)); });
    try {
      const cust: any[] = JSON.parse(localStorage.getItem(`pageData_customer_customer-info_${owner}`) || '[]');
      cust.forEach((c: any) => { if (c && c.name) names.add(String(c.name)); });
    } catch { /* ignore */ }
    let users: any[] = [];
    try { users = JSON.parse(localStorage.getItem('registeredUsers') || '[]'); } catch { users = [] }
    const ownCompany = getOwnCompanyName(owner);
    names.forEach(n => {
      if (out.some(o => o.label === n)) return;
      const cands = users.filter((u: any) => String(u?.companyName || '').trim() === n);
      if (cands.length === 0) return;
      const hit = cands.find((c: any) => {
        try {
          const b: any[] = JSON.parse(localStorage.getItem('boundPurchasers_' + c.username) || '[]');
          return b.some((bp: any) => bp.purchaserUsername === owner || bp.purchaserName === ownCompany);
        } catch { return false; }
      }) || (cands.length === 1 ? cands[0] : null);
      if (hit) push(hit.username, n);
    });
    return out;
  }, [returnRegVisible, dataSource, getDataOwner]);
  const returnRegLinkedOptions = useMemo(() => (dataSource as any[])
    .filter(r => r && r.docType !== 'return' && r.outboundNo)
    .map(r => ({
      value: String(r.outboundNo),
      label: `${r.outboundNo}（${r.customerName || '-'} ¥${Number(r.totalAmount || 0).toFixed(2)}）`,
      items: (Array.isArray(r.items) ? r.items : []).map((it: any) => ({ productCode: it.productCode || '', productName: it.productName || '', color: it.color || '', spec: it.spec || '', quantity: Number(it.quantity) || 0, unitPrice: Number(it.price ?? it.unitPrice) || 0 })),
    })), [dataSource]);

  /** 退货登记提交：本端负数退货行 → 镜像采购商采购账单 → 库存联动（供方退货仓入库/采方退货出库） */
  const handleReturnRegister = useCallback((p: ReturnRegisterPayload) => {
    const owner = getDataOwner();
    if (dataSource.some((r: any) => r.id === p.returnNo || r.outboundNo === p.returnNo)) { message.warning(`退货单 ${p.returnNo} 已登记，请勿重复提交`); return; }
    const now = new Date().toLocaleString('zh-CN');
    const operator = getCurrentUserDisplayName();
    const row = buildSupplierReturnRow(p, { customerName: p.counterpartyName, counterpartyUsername: p.counterpartyUsername, now }) as any;
    const updated = [row, ...dataSource];
    setDataSource(updated);
    const storageKey = `pageData_customer_bill-detail_${owner}`;
    const json = JSON.stringify(updated);
    safeSetItem(storageKey, json);
    saveDataset(storageKey, json);
    // 不再即时镜像写采购商采购账单：退货与正常账单一致走对账管理流程，
    // 对方负数账单由对账完成（completeRecon）时在本端自建（避免跨端整键覆盖擦除对方数据）
    // 库存联动：供应商侧退货仓入库 + 采购商侧退货出库
    writeReturnStockFlows(p, {
      supplierOwner: owner, purchaserOwner: p.counterpartyUsername, operator,
      supplierCompanyName: getOwnCompanyName(owner), purchaserCompanyName: p.counterpartyName,
    });
    setReturnRegVisible(false);
    message.success(`退货单 ${p.returnNo} 已登记：负数退货账单已生成并同步至采购商平台`);
  }, [dataSource, getDataOwner, getCurrentUserDisplayName]);

  // 账单明细：确认无误
  const handleBillConfirm = useCallback((record: Record<string, any>) => {
    // 与按钮渲染同源判据：订单来源账单需已发货/已完成，且已发起对账的行不可本端单方确认
    if (!canConfirmBill(record)) {
      message.warning(orderStatusOkForRecon(record)
        ? `账单当前对账状态为“${reconStateOf(record)}”，无需重复确认`
        : `订单状态为“${record.orderStatus || '未知'}”，仅“已发货/已完成”状态可确认无误`);
      return;
    }
    Modal.confirm({
      title: '确认对账无误',
      content: `确定账单 ${record.id}（客户：${record.customerName || '—'}）已对账确认无误吗？`,
      okText: '确认无误',
      cancelText: '取消',
      onOk: () => {
        const user = localStorage.getItem('username') || 'admin';
        let displayName = user;
        try {
          const users = JSON.parse(localStorage.getItem('registeredUsers') || '[]');
          const u = users.find((x: any) => x.username === user);
          if (u) displayName = u.contactPerson || u.companyName || user;
        } catch { /* ignore */ }
        const now = new Date().toLocaleString('zh-CN');
        setDataSource(prev => prev.map(r => r.key === record.key ? { ...r, reconResult: '确认无误', diffDesc: '', supplierReconPerson: displayName, confirmTime: now } : r));
        // 持久化到 localStorage
        try {
          const owner = getDataOwner();
          const storageKey = `pageData_customer_bill-detail_${owner}`;
          const saved = localStorage.getItem(storageKey);
          if (saved) {
            const data = JSON.parse(saved);
            const idx = data.findIndex((r: any) => r.id === record.id || r.key === record.key);
            if (idx >= 0) {
              data[idx].reconResult = '确认无误';
              data[idx].diffDesc = '';
              data[idx].supplierReconPerson = displayName;
              data[idx].confirmTime = now;
              data[idx].billLog = appendBillLogEntry(data[idx].billLog, '确认无误', displayName, `账单 ${record.id} 供应商确认无误`);
              localStorage.setItem(storageKey, JSON.stringify(data));
            }
          }
        } catch { /* ignore */ }
        // 闭环：在途对账记录携带“供应商已确认”标记（同步至采购商侧可见）
        try {
          const owner1 = getDataOwner();
          const live0 = loadRoleRecords('supplier', owner1).filter((x: any) => (record.id && x.orderNo === record.id) || (record.outboundNo && String(x.docNo || '').trim() === String(record.outboundNo).trim()));
          if (live0.length) upsertRecords(live0.map((x: any) => ({ ...x, supplierConfirmed: true, supplierConfirmedBy: displayName, supplierConfirmedAt: now })));
        } catch { /* ignore */ }
        message.success(`账单 ${record.id} 已确认无误`);
      },
    });
  }, [getDataOwner]);

  // 账单明细（会计账薄版本）：监听对账结果与已入账金额变更，自动写入/重写/删除对应会计分录
  const prevReconRef = useRef<Record<string, string>>({});
  const prevReconAmtRef = useRef<Record<string, number>>({});
  useEffect(() => {
    if (pageConfig?.title !== '账单明细') { prevReconRef.current = {}; prevReconAmtRef.current = {}; return; }
    const owner = getDataOwner();
    if (!isAccountingMode(owner)) { prevReconRef.current = {}; prevReconAmtRef.current = {}; return; }
    const next: Record<string, string> = {};
    const nextAmt: Record<string, number> = {};
    dataSource.forEach((r: any) => { const k = String(r.key || r.id); next[k] = r.reconResult || ''; nextAmt[k] = Number(r.totalAmount) || 0; });
    const prev = prevReconRef.current;
    const prevAmt = prevReconAmtRef.current;
    if (Object.keys(prev).length > 0) {
      const IN = RECON_BOOKED;
      dataSource.forEach((r: any) => {
        const k = String(r.key || r.id);
        const cur = reconStateOf(r); const old = prev[k] || '';
        const srcKey = `bill-recon-${r.id || k}`;
        if (IN.includes(cur)) {
          const amount = Number(r.totalAmount) || 0;
          const entered = !IN.includes(old);
          // 已入账行金额被改写（历史无锁定数据/手工调整）时按 sourceKey 幂等重写分录，
          // 保证台账与账单金额不脱钩；writeAutoEntries 对金额≤0 只返回空串不清旧分录，需显式删除
          const amtMoved = !entered && prevAmt[k] !== undefined && Math.abs(amount - prevAmt[k]) >= 0.005;
          if (entered || amtMoved) {
            if (amount > 0) {
              writeAutoEntries(owner, { sourceKey: srcKey, debitSubject: '应收账款', creditSubject: '库存商品', amount, summary: `销售${r.customerName || ''}商品（账单${r.id || ''}）对账结果：${cur}` });
            } else {
              removeAutoEntries(owner, srcKey);
            }
          }
        } else if (IN.includes(old)) {
          removeAutoEntries(owner, srcKey);
        }
      });
    }
    prevReconRef.current = next;
    prevReconAmtRef.current = nextAmt;
  }, [dataSource, pageConfig?.title, getDataOwner]);

  // 账单明细：发起对账核心逻辑（写入对账管理共享存储，采购商平台按单据编号自动匹配核对）
  // silent=true 时不弹单项提示（批量/自动场景），返回 { ok, reason } 供汇总
  const initReconCore = useCallback((record: Record<string, any>, silent?: boolean): { ok: boolean; reason: string } => {
    const owner = getDataOwner();
    // 客户名称为空时不能发起对账
    if (!record.customerName || !String(record.customerName).trim()) {
      const reason = '客户名称为空，无法发起对账';
      if (!silent) message.warning(reason);
      return { ok: false, reason };
    }
    // 账单来源于订单时，仅已发货/已完成状态允许发起对账（与按钮渲染同源判据，防两端各写一套）
    if (!orderStatusOkForRecon(record)) {
      const reason = `订单状态为“${record.orderStatus || '未知'}”，仅“已发货/已完成”状态可发起对账`;
      if (!silent) message.warning(reason);
      return { ok: false, reason };
    }
    // 已在途/已入账的行不可重复发起（行内按钮已隐藏，此处兜底批量与自动发起入口）
    if (!canInitRecon(record)) {
      const reason = `账单当前对账状态为“${reconStateOf(record)}”，无需重复发起对账`;
      if (!silent) message.warning(reason);
      return { ok: false, reason };
    }
    // 客户类型校验：仅“已合作采购商”可发起对账。
    // 凭证优先 + 改名兼容：名称快照可能因改名滞后，先按名称/账号/公司编号直配客户行；
    // 未命中再按名称（含 company_renames 改名链）反查注册账号，用账号/公司编号二次匹配客户行；
    // 最后回退 boundPurchasers 合作镜像判定合作状态，确保改名后仍可发起对账
    const customers = loadAllCustomersFromStorage();
    const recName = String(record.customerName || '').trim();
    const recUser = String(record.customerUsername || '').trim();
    const recNo = String(record.customerNo || '').trim();
    const nameOfCust = (c: any) => String(c?.name || '').trim();
    let cust: any = customers.find(c => nameOfCust(c) === recName)
      || customers.find(c => !!recUser && (c.purchaserUsername === recUser || (c as any).username === recUser))
      || customers.find(c => !!recNo && (c.purchaserNo === recNo || (c as any).companyNo === recNo))
      || null;
    let cpUser: any = null;   // 对手方注册账号（真实凭证来源）
    let boundRec: any = null; // 供应商侧合作镜像（boundPurchasers_<owner>）
    let supplierName = owner;
    try {
      const users: any[] = JSON.parse(localStorage.getItem('registeredUsers') || '[]');
      // 改名链折叠：任意历史名 → 最新名（A→B→C 折叠为 A→C、B→C）
      let renames: any[] = [];
      try { renames = JSON.parse(localStorage.getItem('company_renames') || '[]'); } catch { renames = []; }
      const chain = new Map<string, string>();
      (Array.isArray(renames) ? renames : []).slice().sort((a: any, b: any) => (Number(a?.ts) || 0) - (Number(b?.ts) || 0)).forEach((r: any) => {
        const on = String(r?.oldName || '').trim();
        const nn = String(r?.newName || '').trim();
        if (!on || !nn || on === nn) return;
        chain.forEach((v, k) => { if (v === on) chain.set(k, nn); });
        chain.set(on, nn);
      });
      const latestName = (n: string): string => {
        let t = String(n || '').trim();
        let guard = 0;
        while (chain.has(t) && guard++ < 10) t = chain.get(t) as string;
        return t;
      };
      const findUser = (n: string): any => {
        const t = String(n || '').trim();
        if (!t) return null;
        const ln = latestName(t);
        return users.find(x => String(x?.companyName || '').trim() === t)
          || users.find(x => String(x?.companyName || '').trim() === ln)
          || users.find(x => String(x?.companyShortName || '').trim() === t)
          || users.find(x => String(x?.companyNo || '').trim() === t)
          || null;
      };
      cpUser = findUser(recName)
        || (recUser ? users.find(x => x.username === recUser) : null)
        || (recNo ? users.find(x => String(x.companyNo || '') === recNo || String(x.companyShortName || '') === recNo) : null)
        || null;
      // 已命中未合作的客户行不回退，避免把直接客户误判为采购商
      if (!cust || cust.type !== 'purchaser') {
        cust = customers.find(c => !!cpUser?.username && c.purchaserUsername === cpUser.username)
          || customers.find(c => !!cpUser?.companyNo && c.purchaserNo === cpUser.companyNo)
          || customers.find(c => !!cpUser?.companyName && nameOfCust(c) === String(cpUser.companyName).trim())
          || cust;
      }
      const su = users.find((x: any) => x.username === owner);
      if (su) supplierName = su.companyName || su.contactPerson || owner;
    } catch { /* ignore */ }
    // 客户行缺失或不是采购商行（可能是同名直接客户）时，用合作镜像（双凭证：账号/公司编号，名称兜底）判定合作关系
    if (!cust || cust.type !== 'purchaser') {
      try {
        const bps: any[] = JSON.parse(localStorage.getItem(`boundPurchasers_${owner}`) || '[]');
        boundRec = bps.find(bp => {
          if (!bp) return false;
          if (cpUser && ((!!cpUser.username && bp.purchaserUsername === cpUser.username) || (!!cpUser.companyNo && bp.purchaserNo === cpUser.companyNo))) return true;
          if (recUser && bp.purchaserUsername === recUser) return true;
          if (recNo && bp.purchaserNo === recNo) return true;
          return !!recName && String(bp.purchaserName || '').trim() === recName;
        }) || null;
      } catch { /* ignore */ }
    }
    const coopFromCust = !!cust && cust.type === 'purchaser' && cust.bindStatus !== '已解除合作';
    const coopFromBound = !!boundRec && boundRec.status !== 'terminated' && boundRec.status !== 'terminating';
    // 采购商客户行优先（含已解除合作否定）；否则以合作镜像为准
    const isCoopPurchaser = cust && cust.type === 'purchaser' ? coopFromCust : coopFromBound;
    if (!isCoopPurchaser) {
      const typeLabel = cust ? (cust.type === 'direct' ? '直接客户' : '合作过（已解除合作）') : (boundRec ? '合作已终止' : '未合作客户');
      const reason = `客户类型为${typeLabel}，仅已合作采购商可发起对账`;
      if (!silent) {
        // 正方形提示窗口：屏幕上下左右居中显示
        Modal.warning({
          title: '客户类型不符',
          content: (
            <div style={{ height: 204, display: 'flex', alignItems: 'center', justifyContent: 'center', textAlign: 'center' }}>
              <span style={{ fontSize: 14, lineHeight: '24px' }}>
                客户「{record.customerName || '—'}」的{reason}
              </span>
            </div>
          ),
          centered: true,
          width: 360,
          okText: '知道了',
        });
      }
      return { ok: false, reason };
    }
    // 凭证落定：账号 > 客户行镜像 > 记录快照；编号同理（公司编号/采购商编号）
    const customerUsername = cust?.purchaserUsername || cpUser?.username || recUser || '';
    const customerNo = recNo || cust?.purchaserNo || cpUser?.companyNo || '';
    // 客户名称以注册账号真源为准（改名后镜像/快照可能滞后）
    const resolvedCustomerName = String(cpUser?.companyName || cust?.name || record.customerName || '').trim();
    let products: any[] = [];
    try { products = JSON.parse(localStorage.getItem(`pageData_basic-data_product-list_${owner}`) || '[]'); } catch { /* ignore */ }
    const nameOf = (code: string) => {
      const p = products.find((x: any) => x.productCode === code);
      return p ? (p.shortName || p.productName || p.name || code) : code;
    };
    const styleOf = (it: any) => {
      if (it?.styleCode) return String(it.styleCode);
      const prod = products.find((x: any) => x.productCode === it?.productCode);
      if (prod?.styleCode) return String(prod.styleCode);
      return String(it?.productCode || '').split('-')[0] || '未知款式';
    };
    const items: any[] = Array.isArray(record.items) ? record.items : [];
    const styleMap = new Map<string, number>();
    items.forEach((it: any) => {
      const sc = styleOf(it);
      styleMap.set(sc, (styleMap.get(sc) || 0) + (Number(it.quantity) || 0));
    });
    const details = items.map((it: any, i: number) => ({
      itemNo: it.productCode || `ITEM-${i + 1}`,
      styleCode: styleOf(it),
      itemName: nameOf(it.productCode || ''),
      ourQty: Number(it.quantity) || 0,
      theirQty: 0,
      ourPrice: Number(it.price) || 0,
      theirPrice: 0,
      ourSubTotal: (Number(it.quantity) || 0) * (Number(it.price) || 0),
      theirSubTotal: 0,
      match: false,
    }));
    const now = new Date().toISOString().slice(0, 10);
    // 重新发起对账时恢复旧的关联状态（matchedBillKey 使用之前关联的采购商账单key）
    const matchedBillKey = record.matchedPurchaserBillKey || '';
    const rec: Record<string, any> = {
      key: `recon-${record.id || record.key}-${Date.now()}`,
      docNo: record.outboundNo || record.id || '',
      orderNo: record.id || '',
      reconType: 'customer',
      counterparty: record.customerName || '',
      counterpartyCode: customerUsername,
      supplierUsername: owner,
      supplierName,
      customerName: resolvedCustomerName,
      customerUsername,
      customerNo,
      initiator: 'supplier',
      supplierReconPerson: getCurrentUserDisplayName(), // 供方发起/对账人姓名（采购商侧账单“供应商对账人”显示源）
      ourAmount: Number(record.totalAmount) || 0,
      theirAmount: 0,
      reconResult: 'pending',
      diffDesc: '等待采购商入账/关联单据',
      date: now,
      ourEntryDate: now,
      theirEntryDate: '-',
      details,
      styleCompare: Array.from(styleMap.entries()).map(([styleCode, qty]) => ({ styleCode, ourQty: qty, theirQty: 0 })),
      source: 'bill',
      ...(matchedBillKey ? { matchedBillKey } : {}),
    };
    // 供应商平台独立对账库查重 + 落库（同时写入采购商侧库，保证双端可见）
    const existingRecons = loadRoleRecords('supplier', String(rec.supplierUsername || owner));
    if (existingRecons.some((r: any) => r.source === 'bill' && r.orderNo === record.id)) {
      if (!silent) message.warning('该账单已发起对账，请勿重复发起');
      return { ok: false, reason: '已发起对账，请勿重复发起' };
    }
    upsertRecords([rec]);
    // 记录发起对账日志
    let newBillLog = (record as any).billLog;
    try {
      newBillLog = appendBillLogEntry(newBillLog, '发起对账', undefined, `单据编号 ${rec.docNo} 已发送至采购商对账管理`);
      const storageKey = `pageData_customer_bill-detail_${owner}`;
      const saved = localStorage.getItem(storageKey);
      if (saved) {
        const data = JSON.parse(saved);
        const idx = data.findIndex((r: any) => r.id === record.id || r.key === record.key);
        if (idx >= 0) {
          data[idx].billLog = newBillLog;
          data[idx].supplierReconciler = getCurrentUserDisplayName();
          // 发起必须把在途态一并落库：buildBillDetailRows 重载时按 prev.reconResult 回填，
          // 只改内存不落库（自动/批量发起后刷新）行会退回「待对账」——
          // 表现即为撤回对账按钮消失、再点发起被查重挡回「请勿重复发起」的死锁
          data[idx].reconResult = '已发起对账';
          // 凭证回填：改名导致名称快照与客户档案分叉时，后续联动一律以账号/公司编号为准
          if (customerUsername) data[idx].customerUsername = customerUsername;
          if (customerNo) data[idx].customerNo = customerNo;
          if (resolvedCustomerName && data[idx].customerName !== resolvedCustomerName) data[idx].customerName = resolvedCustomerName;
          localStorage.setItem(storageKey, JSON.stringify(data));
        }
      }
    } catch { /* ignore */ }
    setDataSource(prev => prev.map(r => r.key === record.key ? {
      ...r, reconResult: '已发起对账', supplierReconciler: getCurrentUserDisplayName(), billLog: newBillLog,
      customerName: resolvedCustomerName, customerUsername, customerNo,
    } : r));
    if (!silent) message.success(`已发起对账，单据编号 ${rec.docNo} 已发送至采购商对账管理`);
    return { ok: true, reason: '' };
  }, [getDataOwner]);

  // 账单明细：批量发起对账（勾选多条账单一键发起）
  const handleBatchInitRecon = useCallback(() => {
    if (selectedRowKeys.length === 0) { message.warning('请先勾选要发起对账的账单'); return; }
    const records = dataSource.filter(r => selectedRowKeys.includes(r.key));
    const fails: { name: string; reason: string }[] = [];
    let okCount = 0;
    records.forEach(r => {
      const res = initReconCore(r, true);
      if (res.ok) okCount++;
      else fails.push({ name: `${r.id || ''}${r.customerName ? `（${r.customerName}）` : ''}`, reason: res.reason });
    });
    if (okCount > 0) message.success(`已对 ${okCount} 条账单发起对账，发送至采购商平台对账管理`);
    if (fails.length > 0) {
      Modal.warning({
        title: `部分账单未发起对账（${fails.length} 条）`,
        content: (
          <div style={{ maxHeight: 300, overflowY: 'auto' }}>
            {fails.map((f, i) => (<div key={i} style={{ marginBottom: 6 }}>• {f.name}：{f.reason}</div>))}
          </div>
        ),
        centered: true,
        width: 420,
        okText: '知道了',
      });
    }
  }, [selectedRowKeys, dataSource, initReconCore]);

  // 自动发起对账设置（账单创建 N 小时后自动发起；可限定指定客户；未保存过默认开启）
  const [autoReconVisible, setAutoReconVisible] = useState(false);
  const [autoReconEnabled, setAutoReconEnabled] = useState(true);
  const [autoReconDelay, setAutoReconDelay] = useState<number>(1);
  const [autoReconScope, setAutoReconScope] = useState<'all' | 'selected'>('all');
