  // 加工订单：半成品详情+最新报价弹窗（点击加工单号/新报价状态打开）
  const [mktDetailRec, setMktDetailRec] = useState<any>(null);
  // 加工厂详情+报价内容弹窗（点击报价记录中的加工厂名称打开）
